INSERT INTO questions (id, public_id, version, status, pathway_id, primary_subtopic_id, difficulty, question_type, sector, origin, published_at, created_at, updated_at) VALUES ('134aaf8a-14da-4783-973c-b70e302bcea4', 'ACP-Q-1866', 1, 'published', 'p-mpharm', 'sub-paracetamol-tox', 'hard', 'sba', 'gp', 'human', 1789655696, 1789655696, 1789655696);
INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('5fab7d19-3eb6-4b8c-be1f-37e89c8c7ccf', '134aaf8a-14da-4783-973c-b70e302bcea4', 'A 22-year-old female patient A 24-year-old patient reports ingesting 20 g of paracetamol in divided doses over the past 14 hours ("staggered overdose"). Baseline blood tests show normal ALT and normal creatinine. (Case Ref: POISONING-EMERGENCY-1866). Relevant physiological and medication history have been reviewed.', 'What is the mandatory clinical treatment decision regarding Acetylcysteine?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1d726fe6-dbca-4705-bb3c-72ce70b2f7db', '134aaf8a-14da-4783-973c-b70e302bcea4', 'A', 'Initiate IV Acetylcysteine immediately without waiting for serum paracetamol levels or nomogram plotting', 1, 'Correct. In staggered paracetamol overdoses (taken over > 1 hour), the paracetamol treatment nomogram CANNOT be used. Acetylcysteine must be commenced immediately regardless of the serum paracetamol concentration.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('65992a83-72b8-41b8-b545-8d6ce920427f', '134aaf8a-14da-4783-973c-b70e302bcea4', 'B', 'Wait for the 4-hour serum paracetamol level and plot on the single-ingestion nomogram curve', 0, 'Fatal error. The nomogram is validated ONLY for acute single ingestions within 4-15 hours. Staggered overdoses render the nomogram uninterpretable.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a44b3a89-a5cd-4d8f-9c69-f935138555d0', '134aaf8a-14da-4783-973c-b70e302bcea4', 'C', 'Administer Oral Activated Charcoal 50 g at 14 hours post-ingestion', 0, 'Ineffective and contraindicated. Activated charcoal is only effective within 1 hour of ingestion and impairs oral antidotes.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('7060e183-3187-46cd-958f-7a6c9af2f40a', '134aaf8a-14da-4783-973c-b70e302bcea4', 'D', 'Withhold acetylcysteine because baseline transaminases (ALT) are currently normal', 0, 'Fatal error. ALT rises 24-48 hours after ingestion; waiting for hepatotoxicity before treating causes irreversible liver failure.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1ef66ca1-fe68-4f84-9a73-cdbb11432a3f', '134aaf8a-14da-4783-973c-b70e302bcea4', 'E', 'Stop acetylcysteine infusion immediately if mild flush develops without anaphylactoid assessment', 0, 'Incorrect management. Common non-IgE mediated reactions can be managed by pausing infusion, giving antihistamine, and restarting at slower rate.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('27f6e5f3-f0e8-47cc-9958-f2ac13a1ffb4', '134aaf8a-14da-4783-973c-b70e302bcea4', 'Never use the paracetamol nomogram for staggered overdoses. Start Acetylcysteine immediately.', 'Snap 12-hour or simplified 2-bag IV acetylcysteine regimens reduce adverse hypersensitivity reactions. Reference: TOXBASE & MHRA Drug Safety Update: Acetylcysteine for paracetamol overdose.', 'TOXBASE & MHRA Drug Safety Update: Acetylcysteine for paracetamol overdose', 1789655696, 1789655696);
